module.exports=[89797,a=>{"use strict";let b=[{chapterNumber:1,nameSanskrit:"अर्जुनविषादयोग",nameEnglish:"The Yoga of Arjuna's Dejection (Arjuna Vishada Yoga)",summary:"Setting the scene on the battlefield of Kurukshetra, Arjuna is overcome with grief and compassion upon seeing his relatives, teachers, and friends arrayed for battle. He drops his weapons, unable to fight.",keyThemes:["Duty","Dilemma","Attachment","Grief"],yogaPath:"Preparation for Yoga",totalVerses:47},{chapterNumber:2,nameSanskrit:"साङ्ख्ययोग",nameEnglish:"The Yoga of Knowledge (Sankhya Yoga)",summary:"Krishna begins his teachings by explaining the eternal nature of the soul (Atman) and the temporary nature of the body. He introduces Karma Yoga—acting without attachment to the results.",keyThemes:["Immortality of the Soul","Duty","Equanimity","Sthitaprajna (The person of steady wisdom)"],yogaPath:"Jnana & Karma Yoga",totalVerses:72},{chapterNumber:3,nameSanskrit:"कर्मयोग",nameEnglish:"The Yoga of Action (Karma Yoga)",summary:"Krishna explains why one must perform their prescribed duties. He clarifies that action is superior to inaction and that the world is bound by action unless it is performed as a sacrifice.",keyThemes:["Sacrifice","Duty","Setting an Example","Overcoming Desire"],yogaPath:"Karma Yoga",totalVerses:43},{chapterNumber:4,nameSanskrit:"ज्ञानकर्मसंन्यासयोग",nameEnglish:"The Yoga of Knowledge and the Disciplines of Action",summary:"Krishna reveals the ancient history of this spiritual science and explains the nature of His divine descent (Avatar). He describes how transcendental knowledge burns away karmic reactions.",keyThemes:["Avatara (Divine Descent)","Transcendental Knowledge","Spiritual Sacrifice"],yogaPath:"Jnana & Karma Yoga",totalVerses:42},{chapterNumber:5,nameSanskrit:"कर्मसंन्यासयोग",nameEnglish:"The Yoga of Renunciation of Action",summary:"Krishna resolves the apparent conflict between renouncing work and working with devotion, explaining that acting in inner detachment and dedicating fruits to God is true renunciation.",keyThemes:["True Renunciation","Detachment","Action in Inaction","Inner Peace"],yogaPath:"Karma Sanyasa",totalVerses:29},{chapterNumber:6,nameSanskrit:"ध्यानयोग",nameEnglish:"The Yoga of Meditation (Dhyana Yoga)",summary:"Krishna outlines the practical steps of meditation (Dhyana), including lifestyle, posture, and concentration. He assures Arjuna that efforts in spiritual practice are never lost, even across lifetimes.",keyThemes:["Meditation","Mind Control","Balance","Reincarnation of a Yogi"],yogaPath:"Dhyana/Raja Yoga",totalVerses:47},{chapterNumber:7,nameSanskrit:"ज्ञानविज्ञानयोग",nameEnglish:"The Yoga of Knowledge and Wisdom",summary:"Krishna describes His material and spiritual energies holding the universe together. He identifies four types of pious people who surrender to Him and discusses the illusion of Maya.",keyThemes:["Material & Spiritual Energy","Maya (Illusion)","Surrender","The Four Types of Seekers"],yogaPath:"Bhakti & Jnana",totalVerses:30},{chapterNumber:8,nameSanskrit:"अक्षरब्रह्मयोग",nameEnglish:"The Yoga of the Imperishable Brahman",summary:"Krishna explains the significance of one's thoughts at the time of death and how to remember the Divine unceasingly to attain the supreme, imperishable abode.",keyThemes:["Brahman","Death and the Afterlife","Cycles of Creation","Yogic Remembrance"],yogaPath:"Bhakti & Raja Yoga",totalVerses:28},{chapterNumber:9,nameSanskrit:"राजविद्याराजगुह्ययोग",nameEnglish:"The Yoga of the Sovereign Science and Sovereign Secret",summary:"A profound chapter revealing the supreme, hidden knowledge of Krishna's absolute, all-pervading nature, emphasizing that pure devotion (Bhakti) is the direct path to liberation.",keyThemes:["The Sovereign Secret","Divine Sovereignty","Unconditional Devotion","Universal Grace"],yogaPath:"Bhakti Yoga",totalVerses:34},{chapterNumber:10,nameSanskrit:"विभूतियोग",nameEnglish:"The Yoga of Divine Manifestations (Vibhuti Yoga)",summary:"Krishna describes His opulent manifestations, showing how all beauty, power, and wisdom in the universe are merely a spark of His infinite glory.",keyThemes:["Divine Opulence","Manifestations of God in Nature","The Source of All"],yogaPath:"Bhakti Yoga",totalVerses:42},{chapterNumber:11,nameSanskrit:"विश्वरूपदर्शनयोग",nameEnglish:"The Yoga of the Vision of the Cosmic Form",summary:"At Arjuna's request, Krishna reveals His awe-inspiring Cosmic Form (Vishvarupa), encompassing the entire universe, terrifying time, and infinite expanses.",keyThemes:["The Cosmic Form","Time as the Destroyer","Total Surrender","Triumph of Devotion"],yogaPath:"Bhakti Yoga",totalVerses:55},{chapterNumber:12,nameSanskrit:"भक्तियोग",nameEnglish:"The Yoga of Devotion (Bhakti Yoga)",summary:"Krishna explains the path of loving devotion, comparing the worship of His personal form to the worship of the formless infinite. He lists the qualities of a devotee dear to Him.",keyThemes:["Ways to Worship","Qualities of a True Devotee","Love and Equanimity"],yogaPath:"Bhakti Yoga",totalVerses:20},{chapterNumber:13,nameSanskrit:"क्षेत्रक्षेत्रज्ञविभागयोग",nameEnglish:"The Yoga of Distinction Between the Field and the Knower",summary:"Krishna introduces the concepts of the Field (the physical body/matter) and the Knower of the Field (the soul/Paramatman), distinguishing between material nature and consciousness.",keyThemes:["Prakriti and Purusha","The Field (Kshetra)","The Knower (Kshetrajna)","True Knowledge"],yogaPath:"Jnana Yoga",totalVerses:34},{chapterNumber:14,nameSanskrit:"गुणत्रयविभागयोग",nameEnglish:"The Yoga of the Division of the Three Gunas",summary:"An exploration of the three modes of material nature (Gunas): Sattva (goodness), Rajas (passion), and Tamas (ignorance), explaining how they bind the soul and how to transcend them.",keyThemes:["The Three Gunas","Sattva, Rajas, and Tamas","Transcending Material Nature"],yogaPath:"Jnana Yoga",totalVerses:27},{chapterNumber:15,nameSanskrit:"पुरुषोत्तमयोग",nameEnglish:"The Yoga of the Supreme Person (Purushottama Yoga)",summary:"Using the metaphor of an inverted banyan tree, Krishna describes the material world and the process of detachment. He identifies Himself as the Supreme Being beyond the fallible and infallible.",keyThemes:["The Cosmic Tree","Detachment","The Supreme Person (Purushottama)"],yogaPath:"Jnana & Bhakti",totalVerses:20},{chapterNumber:16,nameSanskrit:"दैवासुरसम्पद्विभागयोग",nameEnglish:"The Yoga of Division Between Divine and Demonic Endowments",summary:"Krishna lists the divine qualities that lead to liberation and the demonic or materialistic qualities that lead to bondage and suffering, urging adherence to scriptural guidance.",keyThemes:["Divine Nature","Demonic Nature","The Gates to Hell (Lust, Anger, Greed)","Scriptural Authority"],yogaPath:"Preparation for Yoga",totalVerses:24},{chapterNumber:17,nameSanskrit:"श्रद्धात्रयविभागयोग",nameEnglish:"The Yoga of the Threefold Division of Faith",summary:"Krishna explains how faith, food, sacrifices, austerities, and charity are categorized according to the three Gunas (Sattva, Rajas, Tamas). Includes the explanation of 'Om Tat Sat'.",keyThemes:["Faith according to Gunas","Food and Temperament","Types of Austerity","Om Tat Sat"],yogaPath:"Jnana Yoga",totalVerses:28},{chapterNumber:18,nameSanskrit:"मोक्षसंन्यासयोग",nameEnglish:"The Yoga of Liberation by Renunciation",summary:"The conclusion of the Gita, summarizing all previous teachings. Krishna defines true renunciation (Tyaga), explains the mechanics of action, and delivers His supreme instruction: surrender wholly to Him.",keyThemes:["Renunciation vs. Relinquishment","The Mechanics of Action","Understanding Duty","Supreme Surrender"],yogaPath:"Karma, Jnana & Bhakti Fusion",totalVerses:78}];function c(a){return b.find(b=>b.chapterNumber===a)}a.s(["bgChapters",0,b,"getBgChapterByNumber",()=>c])},93424,a=>{"use strict";let b=[{id:"1.2",chapter:1,verse:2,sanskritDevanagari:"सञ्जय उवाच |\nदृष्ट्वा तु पाण्डवानीकं व्यूढं दुर्योधनस्तदा |\nआचार्यमुपसङ्गम्य राजा वचनमब्रवीत् || २ ||",transliteration:"sañjaya uvāca\ndṛṣṭvā tu pāṇḍavānīkaṁ vyūḍhaṁ duryodhanas tadā\nācāryam upasaṅgamya rājā vacanam abravīt",synonyms:"sañjayaḥ uvāca—Sanjaya said; dṛṣṭvā—after seeing; tu—but; pāṇḍava-anīkam—the soldiers of the Pandavas; vyūḍham—arranged in a military phalanx; duryodhanaḥ—King Duryodhana; tadā—at that time; ācāryam—the teacher (Drona); upasaṅgamya—approaching; rājā—the king; vacanam—words; abravīt—spoke.",translation:"Sanjaya said: O King, after looking over the army gathered by the sons of Pandu, King Duryodhana went to his teacher and spoke the following words:",commentaries:[{author:"Swami Gambhirananda (Advaita Vedanta)",text:"Duryodhana, though a king, becomes fearful upon seeing the formidable military arrangement of the Pandavas. He approaches his teacher Drona out of diplomatic cunning, masking his fear with action."}],practicalApplication:"Like Duryodhana, when our ego faces a genuinely powerful challenge—especially one aligned with truth (Dharma)—it tries to seek external validation and reassurance. Recognizing this tendency in ourselves is the first step toward true inner confidence."},{id:"1.3",chapter:1,verse:3,sanskritDevanagari:"पश्यैतां पाण्डुपुत्राणामाचार्य महतीं चमूम् |\nव्यूढां द्रुपदपुत्रेण तव शिष्येण धीमता || ३ ||",transliteration:"paśyaitāṁ pāṇḍu-putrāṇām ācārya mahatīṁ camūm\nvyūḍhāṁ drupada-putreṇa tava śiṣyeṇa dhīmatā",synonyms:"paśya—behold; etām—this; pāṇḍu-putrāṇām—of the sons of Pandu; ācārya—O teacher; mahatīm—great; camūm—military force; vyūḍhām—arranged; drupada-putreṇa—by the son of Drupada; tava—your; śiṣyeṇa—disciple; dhī-matā—very intelligent.",translation:"O my teacher, behold the great army of the sons of Pandu, so expertly arranged by your intelligent disciple, the son of Drupada.",commentaries:[{author:"Ramanuja (Vishishtadvaita)",text:"Duryodhana subtly insults Drona by pointing out that Drupada's son, whom Drona himself trained, is now leading the opposing army. It reveals his political manipulative nature, seeking to anger his teacher into fighting harder."}],practicalApplication:"When driven by fear and insecurity, the ego often resorts to subtle manipulation and blame. Observing how we communicate when we feel threatened is a profound sadhana."},{id:"1.20",chapter:1,verse:20,sanskritDevanagari:"अथ व्यवस्थितान्दृष्ट्वा धार्तराष्ट्रान् कपिध्वजः |\nप्रवृत्ते शस्त्रसम्पाते धनुरुद्यम्य पाण्डवः |\nहृषीकेशं तदा वाक्यमिदमाह महीपते || २० ||",transliteration:"atha vyavasthitān dṛṣṭvā dhārtarāṣṭrān kapi-dhvajaḥ\npravṛtte śastra-sampāte dhanur udyamya pāṇḍavaḥ\nhṛṣīkeśaṁ tadā vākyam idam āha mahī-pate",synonyms:"atha—thereupon; vyavasthitān—situated; dṛṣṭvā—looking upon; dhārtarāṣṭrān—the sons of Dhritarashtra; kapi-dhvajaḥ—he whose flag is marked with Hanuman; pravṛtte—while about to engage; śastra-sampāte—in the release of arrows; dhanuḥ—bow; udyamya—taking up; pāṇḍavaḥ—the son of Pandu (Arjuna); hṛṣīkeśam—unto Lord Krishna; tadā—at that time; vākyam—words; idam—these; āha—said; mahī-pate—O King.",translation:"At that time Arjuna, the son of Pandu, seated in the chariot bearing the flag of Hanuman, took up his bow and prepared to shoot his arrows. O King, after looking at the sons of Dhritarashtra drawn in military array, Arjuna then spoke to Lord Krishna these words:",commentaries:[{author:"Swami Sivananda",text:"Arjuna is ready for the battle. The mention of 'Kapi-dhvaja' (Hanuman on the banner) indicates that Arjuna's cause is righteous, supported by divine forces. This marks the turning point where observation turns into a profound existential crisis."}],practicalApplication:"Before any major crisis or transformation, there is often a moment of absolute readiness, immediately followed by the collapse of our certainties. This verse captures the exact moment before Arjuna's ego fractures."},{id:"1.21",chapter:1,verse:21,sanskritDevanagari:"अर्जुन उवाच |\nसेनयोरुभयोर्मध्ये रथं स्थापय मेऽच्युत || २१ ||",transliteration:"arjuna uvāca\nsenayor ubhayor madhye rathaṁ sthāpaya me 'cyuta",synonyms:"arjunaḥ uvāca—Arjuna said; senayoḥ—of the armies; ubhayoḥ—both; madhye—between; ratham—the chariot; sthāpaya—please place; me—my; acyuta—O infallible one.",translation:"Arjuna said: O infallible one, please draw my chariot between the two armies so that I may see those present here, who desire to fight.",commentaries:[{author:"Swami Sivananda",text:"Arjuna asserts a sense of control and heroism, demanding to see his enemies. Yet he addresses Krishna as 'Acyuta' (the infallible), subconsciously recognizing that while he may fail or fall in courage, the Divine does not."}],practicalApplication:"We often ask God or our higher awareness for 'clarity'—asking to see the truth of our situation. We rarely understand how devastating that clarity will be when it arrives."},{id:"1.28",chapter:1,verse:28,sanskritDevanagari:"अर्जुन उवाच |\nदृष्ट्वेमं स्वजनं कृष्ण युयुत्सुं समुपस्थितम् |\nसीदन्ति मम गात्राणि मुखं च परिशुष्यति || २८ ||",transliteration:"arjuna uvāca\ndṛṣṭvemaṁ sva-janaṁ kṛṣṇa yuyutsuṁ samupasthitam\nsīdanti mama gātrāṇi mukhaṁ ca pariśuṣyati",synonyms:"arjunaḥ uvāca—Arjuna said; dṛṣṭvā—after seeing; imam—all these; sva-janam—kinsmen; kṛṣṇa—O Krishna; yuyutsum—all in a fighting spirit; samupasthitam—present; sīdanti—are quivering; mama—my; gātrāṇi—limbs of the body; mukham—mouth; ca—also; pariśuṣyati—is drying up.",translation:"Arjuna said: My dear Krishna, seeing my friends and relatives present before me in such a fighting spirit, I feel the limbs of my body quivering and my mouth drying up.",commentaries:[{author:"Bhaktivedanta Swami (Gaudiya Vaishnavism)",text:"This marks the beginning of Arjuna's vishadayoga (the yoga of dejection). It is not fear of death, but the overwhelming compassion and horror at having to slaughter his own relatives that paralyzes the greatest warrior of the age."}],practicalApplication:"When we truly see the cost of our worldly attachments, the physical body responds with anxiety and resistance. Spiritual growth often begins precisely at the point where our normal coping mechanisms completely fail."},{id:"1.47",chapter:1,verse:47,sanskritDevanagari:"सञ्जय उवाच |\nएवमुक्त्वाऽर्जुनः सङ्ख्ये रथोपस्थ उपाविशत् |\nविसृज्य सशरं चापं शोकसंविग्नमानसः || ४७ ||",transliteration:"sañjaya uvāca\nevam uktvārjunaḥ saṅkhye rathopastha upāviśat\nvisṛjya sa-śaraṁ cāpaṁ śoka-saṁvigna-mānasaḥ",synonyms:"sañjayaḥ uvāca—Sanjaya said; evam—thus; uktvā—saying; arjunaḥ—Arjuna; saṅkhye—in the battlefield; ratha-upasthe—on the seat of the chariot; upāviśat—sat down; visṛjya—putting aside; sa-śaram—along with arrows; cāpam—the bow; śoka—by lamentation; saṁvigna—distressed; mānasaḥ—within the mind.",translation:"Sanjaya said: Having spoken thus on the battlefield, Arjuna cast aside his bow and arrows and sat down on the chariot, his mind overwhelmed with grief.",commentaries:[{author:"Swami Gambhirananda",text:"This verse concludes the first chapter. Arjuna's surrender to grief sets the stage for the teaching. It signifies the complete failure of human intellect to resolve fundamental moral conflicts without divine insight."}],practicalApplication:"When we lay down our 'weapons'—our defenses, arguments, and illusion of control—and sit down in absolute not-knowing, we create the emptiness required for true teaching to flow in. Our deepest breakdowns are often the preconditions for our breakthroughs."},{id:"1.1",chapter:1,verse:1,sanskritDevanagari:"धृतराष्ट्र उवाच |\nधर्मक्षेत्रे कुरुक्षेत्रे समवेता युयुत्सवः |\nमामकाः पाण्डवाश्चैव किमकुर्वत सञ्जय || १ ||",transliteration:"dhṛtarāṣṭra uvāca\ndharma-kṣetre kuru-kṣetre samavetā yuyutsavaḥ\nmāmakāḥ pāṇḍavāś caiva kim akurvata sañjaya",synonyms:"dhṛtarāṣṭraḥ uvāca—King Dhritarashtra said; dharma-kṣetre—in the place of pilgrimage; kuru-kṣetre—in the place named Kurukshetra; samavetāḥ—assembled; yuyutsavaḥ—desiring to fight; māmakāḥ—my party (sons); pāṇḍavāḥ—the sons of Pandu; ca—and; eva—certainly; kim—what; akurvata—did they do; sañjaya—O Sanjaya.",translation:"Dhritarashtra said: O Sanjaya, what did my sons and the sons of Pandu do, when they gathered on the sacred field of Kurukshetra, eager for battle?",commentaries:[{author:"Swami Gambhirananda (Advaita Vedanta)",text:"The field of Kurukshetra is a sacred place of pilgrimage. Dhritarashtra is asking Sanjaya about the activities of his sons and the sons of Pandu, revealing his attachment and anxiety about the outcome, knowing that righteousness (dharma) is on the side of the Pandavas."}],practicalApplication:"Just as the battlefield is called 'Dharmakshetra' (the field of Dharma), our own body and mind are the fields where the internal battle between higher, divine tendencies (the Pandavas) and lower, ego-driven tendencies (the Kauravas) takes place daily."},{id:"2.47",chapter:2,verse:47,sanskritDevanagari:"कर्मण्येवाधिकारस्ते मा फलेषु कदाचन |\nमा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि || ४७ ||",transliteration:"karmaṇy evādhikāras te mā phaleṣu kadācana\nmā karma-phala-hetur bhūr mā te saṅgo 'stv akarmaṇi",synonyms:"karmaṇi—in prescribed duties; eva—certainly; adhikāraḥ—right; te—of you; mā—never; phaleṣu—in the fruits; kadācana—at any time; mā—never; karma-phala—in the result of the work; hetuḥ—cause; bhūḥ—become; mā—never; te—of you; saṅgaḥ—attachment; astu—there should be; akarmaṇi—in not doing prescribed duties.",translation:"You have a right to perform your prescribed duty, but you are not entitled to the fruits of action. Never consider yourself the cause of the results of your activities, and never be attached to not doing your duty.",commentaries:[{author:"Swami Gambhirananda (Advaita Vedanta)",text:"This is the essence of Karma Yoga. By letting go of the anxiety for the results and simply performing the action as an offering, the mind becomes purified. Action must be done, but the clinging to what the action brings must be relinquished."},{author:"Ramanuja (Vishishtadvaita)",text:"To act as an instrument of the Divine, knowing that the ultimate cause of success or failure belongs to the Supreme, liberates the performer from the bondage of Karma."}],practicalApplication:"In modern life, this verse is an antidote to anxiety and burnout. Focus entirely on the process—studying, working, or creating—rather than obsessing over the outcome (grades, promotions, praise). When we detach from the result, the quality of our work actually improves, and we remain peaceful regardless of success or failure."}];function c(a){return b.find(b=>b.id===a)}function d(a){return b.filter(b=>b.chapter===a)}a.s(["bgShlokas",0,b,"getBgShlokaById",()=>c,"getBgShlokasByChapter",()=>d],93424)}];

//# sourceMappingURL=src_data_bb4a38b2._.js.map